def heat_equation_series(f=None, L=None, alpha=None, N=None, x=None, t=None):
    """Heat equation on a rod with ends at zero: Fourier series value. u(x, t) for u_t = alpha u_xx, u(0, t) = u(L, t) = 0, u(x, 0) = f(x) (a polynomial), summed over the first N series terms.
    Formula: u(x, t) = \\sum_{n=1}^{N} b_n e^{-\\alpha (n\\pi/L)^2 t}\\sin\\frac{n\\pi x}{L}
    Inputs:
        f: initial profile f(x), a polynomial
        L: rod length (> 0)
        alpha: diffusivity (> 0)
        N: number of series terms (1 to 500)
        x: position (0 <= x <= L)
        t: time (>= 0)
    Outputs: u (temperature u(x, t) from N terms), b_1 (first sine coefficient)
    See also: help("heat_equation_series")
    """
    given = {k: v for k, v in dict(f=f, L=L, alpha=alpha, N=N, x=x, t=t).items() if v is not None}
    return _P.solve("heat_equation_series", **given)

def heat_ftcs_steps(u=None, r=None, n=None):
    """Explicit finite-difference (FTCS) steps for the heat equation. Advance grid values of u_t = alpha u_xx by n explicit steps u_i <- u_i + r (u_{i+1} - 2 u_i + u_{i-1}), ends held fixed.
    Formula: u_i^{k+1} = u_i^k + r\\left(u_{i+1}^k - 2u_i^k + u_{i-1}^k\\right)
    Inputs:
        u: grid values (first and last are boundary values)
        r: mesh ratio alpha dt / dx^2 (> 0)
        n: number of time steps
    Outputs: u (grid values after n steps), stable_ratio (r <= 1/2)
    See also: help("heat_ftcs_steps")
    """
    given = {k: v for k, v in dict(u=u, r=r, n=n).items() if v is not None}
    return _P.solve("heat_ftcs_steps", **given)

def improved_euler_method(f=None, t0=None, y0=None, h=None, n=None):
    """Improved Euler (Heun) method. Approximate the solution of y' = f(t, y), y(t0) = y0, after n steps of size h with the improved Euler (Heun) method.
    Formula: y_{k+1} = y_k + \\tfrac{h}{2}\\left[f(t_k, y_k) + f(t_{k+1}, y_k + h f(t_k, y_k))\\right]
    Inputs:
        f: right-hand side f(t, y) of y' = f(t, y)
        t0: initial time
        y0: initial value y(t0)
        h: step size (> 0)
        n: number of steps
    Outputs: y_n (approximation of y(t0 + n h)), t_n (final time t0 + n h)
    See also: help("improved_euler_method")
    """
    given = {k: v for k, v in dict(f=f, t0=t0, y0=y0, h=h, n=n).items() if v is not None}
    return _P.solve("improved_euler_method", **given)

def inverse_laplace_transform(F=None, t=None):
    """Inverse Laplace transform of a rational function. f(t) for a strictly proper rational F(s) (any poles, repeated or complex), by residues / partial fractions.
    Formula: f(t) = \\sum_{p}\\operatorname{Res}_{s=p}\\,F(s)e^{st}
    Inputs:
        F: F(s), a rational function of s
        t: time (>= 0)
    Outputs: f (value f(t)), poles (poles of F(s) (canonical order))
    See also: help("inverse_laplace_transform")
    """
    given = {k: v for k, v in dict(F=F, t=t).items() if v is not None}
    return _P.solve("inverse_laplace_transform", **given)

def laplace_equation_rectangle(f=None, a=None, b=None, N=None, x=None, y=None):
    """Laplace's equation on a rectangle: series value. Steady state u_xx + u_yy = 0 on [0, a] x [0, b] with u = f(x) on the top edge y = b and 0 on the other three edges, from N terms.
    Formula: u(x,y) = \\sum_{n=1}^{N} b_n\\frac{\\sinh(n\\pi y/a)}{\\sinh(n\\pi b/a)}\\sin\\frac{n\\pi x}{a}
    Inputs:
        f: top-edge values f(x), a polynomial
        a: width (> 0)
        b: height (> 0)
        N: number of series terms
        x: x in [0, a]
        y: y in [0, b]
    Outputs: u (u(x, y) from N terms)
    See also: help("laplace_equation_rectangle")
    """
    given = {k: v for k, v in dict(f=f, a=a, b=b, N=N, x=x, y=y).items() if v is not None}
    return _P.solve("laplace_equation_rectangle", **given)

def laplace_time_shift(f=None, c=None, s=None):
    """Laplace transform of a delayed function u(t - c) f(t - c). Second shifting theorem: the transform of u(t - c) f(t - c) is e^{-cs} F(s).
    Formula: \\mathcal{L}\\{u(t - c) f(t - c)\\} = e^{-cs}F(s)
    Inputs:
        f: function f(t)
        c: delay (>= 0)
        s: transform variable
    Outputs: F (transform of the delayed function), G (transform of f itself)
    See also: help("laplace_time_shift")
    """
    given = {k: v for k, v in dict(f=f, c=c, s=s).items() if v is not None}
    return _P.solve("laplace_time_shift", **given)

def laplace_transform(f=None, s=None):
    """Laplace transform of a function at a point. F(s) = integral from 0 to infinity of e^{-st} f(t) dt for sums of t^n e^{at} sin/cos(bt) (also sinh, cosh), and the abscissa of convergence.
    Formula: \\mathcal{L}\\{t^n e^{zt}\\}(s) = \\frac{n!}{(s - z)^{n+1}}
    Inputs:
        f: function f(t)
        s: transform variable (s > abscissa)
    Outputs: F (transform value F(s)), sigma (abscissa of convergence (F exists for s > sigma))
    See also: help("laplace_transform")
    """
    given = {k: v for k, v in dict(f=f, s=s).items() if v is not None}
    return _P.solve("laplace_transform", **given)

def linear_drag_velocity(m=None, c=None, g=None, v0=None, t=None):
    """Falling body with linear drag: velocity. Solve m v' = m g - c v with v(0) = v0: velocity at time t and terminal velocity m g / c.
    Formula: v(t) = \\frac{mg}{c} + \\left(v_0 - \\frac{mg}{c}\\right)e^{-ct/m}
    Inputs:
        m: mass (> 0)
        c: linear drag coefficient (> 0)
        g: gravitational acceleration
        v0: initial velocity (downward positive)
        t: time
    Outputs: v (velocity v(t)), v_terminal (terminal velocity m g / c)
    See also: help("linear_drag_velocity")
    """
    given = {k: v for k, v in dict(m=m, c=c, g=g, v0=v0, t=t).items() if v is not None}
    return _P.solve("linear_drag_velocity", **given)

def linear_first_order(a=None, b=None, y0=None, t=None):
    """First-order linear ODE with constant coefficients (integrating factor). Solve y' + a y = b with y(0) = y0 and give y(t) and the equilibrium b/a.
    Formula: y(t) = \\frac{b}{a} + \\left(y_0 - \\frac{b}{a}\\right)e^{-a t}
    Inputs:
        a: coefficient of y (condition: a != 0)
        b: constant forcing
        y0: initial value
        t: time
    Outputs: y (value y(t)), y_steady (equilibrium b/a (the limit when a > 0))
    See also: help("linear_first_order")
    """
    given = {k: v for k, v in dict(a=a, b=b, y0=y0, t=t).items() if v is not None}
    return _P.solve("linear_first_order", **given)

def linear_first_order_exponential_forcing(a=None, b=None, c=None, y0=None, t=None):
    """First-order linear ODE with exponential forcing. Solve y' + a y = b e^{c t}, y(0) = y0, and give y(t) (including the resonant case c = -a).
    Formula: y = \\frac{b}{a+c}e^{ct} + \\left(y_0 - \\frac{b}{a+c}\\right)e^{-at}
    Inputs:
        a: coefficient of y
        b: forcing amplitude
        c: forcing exponent
        y0: initial value
        t: time
    Outputs: y (value y(t)), resonant (c = -a (secular term t e^{-a t}))
    See also: help("linear_first_order_exponential_forcing")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, y0=y0, t=t).items() if v is not None}
    return _P.solve("linear_first_order_exponential_forcing", **given)

def linear_system_solution(A=None, x0=None, t=None):
    """Linear system x' = A x: solution at a time. Solve x' = A x, x(0) = x0 (n up to 6) and give x(t) = e^{At} x0.
    Formula: \\mathbf{x}(t) = e^{At}\\mathbf{x}_0
    Inputs:
        A: n x n coefficient matrix
        x0: initial vector x(0)
        t: time
    Outputs: x (state x(t)), x1 (first component of x(t))
    See also: help("linear_system_solution")
    """
    given = {k: v for k, v in dict(A=A, x0=x0, t=t).items() if v is not None}
    return _P.solve("linear_system_solution", **given)

def linear_system_stability(A=None):
    """Stability of x' = A x (n x n) from the characteristic polynomial. Whether the origin of x' = A x is asymptotically stable and how many eigenvalues have positive real part, without computing eigenvalues.
    Formula: \\det(\\lambda I - A) = \\lambda^n + c_1\\lambda^{n-1} + \\dots + c_n
    Inputs:
        A: n x n coefficient matrix (n <= 8)
    Outputs: stable (asymptotically stable (all eigenvalues Re < 0)), unstable_eigenvalues (number of eigenvalues with Re > 0), char_poly (characteristic polynomial coefficients)
    See also: help("linear_system_stability")
    """
    given = {k: v for k, v in dict(A=A).items() if v is not None}
    return _P.solve("linear_system_stability", **given)

def logistic_harvesting(r=None, K=None, H=None):
    """Logistic growth with constant harvesting: equilibria. Equilibria of dy/dt = r y (1 - y/K) - H, their stability, and the critical (maximum sustainable) harvest.
    Formula: y_\\pm = \\frac{K}{2}\\left(1 \\pm \\sqrt{1 - \\frac{4H}{rK}}\\right)
    Inputs:
        r: growth rate (> 0)
        K: carrying capacity (> 0)
        H: harvest rate (>= 0)
    Outputs: y_high (upper equilibrium (stable)), y_low (lower equilibrium (unstable threshold)), H_critical (maximum sustainable harvest rK/4), stability_high (stability), stability_low (stability)
    See also: help("logistic_harvesting")
    """
    given = {k: v for k, v in dict(r=r, K=K, H=H).items() if v is not None}
    return _P.solve("logistic_harvesting", **given)

def logistic_inflection(P0=None, r=None, K=None):
    """Logistic growth: inflection time and maximum growth rate. When a logistic population grows fastest: the inflection time, the population there (K/2) and the maximum rate rK/4.
    Formula: t^* = \\frac{1}{r}\\ln\\left(\\frac{K}{P_0} - 1\\right),\\; \\dot P_{\\max} = \\frac{rK}{4}
    Inputs:
        P0: initial population (0 < P0 < K/2)
        r: growth rate (> 0)
        K: carrying capacity
    Outputs: t_inflection (time of the inflection point), P_inflection (population at the inflection (K/2)), max_rate (largest growth rate dP/dt (rK/4))
    See also: help("logistic_inflection")
    """
    given = {k: v for k, v in dict(P0=P0, r=r, K=K).items() if v is not None}
    return _P.solve("logistic_inflection", **given)

def logistic_map_fixed_points(r=None):
    """Logistic map: fixed points and their stability. Fixed points of x -> r x (1 - x) in [0, 1], their multipliers f'(x*) and stability.
    Formula: x^* = 1 - \\frac{1}{r},\\quad f'(x^*) = 2 - r
    Inputs:
        r: parameter (0 < r <= 4)
    Outputs: fixed_points (fixed points in [0, 1]), multipliers (f'(x*) at each), stability (stable / unstable / neutral), count (number of fixed points)
    See also: help("logistic_map_fixed_points")
    """
    given = {k: v for k, v in dict(r=r).items() if v is not None}
    return _P.solve("logistic_map_fixed_points", **given)

def logistic_map_lyapunov(r=None, x0=None, n=None):
    """Lyapunov exponent of the logistic map (periodic regime). The Lyapunov exponent of x -> r x (1 - x): the average of ln|f'(x_k)| over n iterations after the orbit settles (fixed point or 2-cycle).
    Formula: \\lambda = \\frac{1}{n}\\sum_{k=1}^{n}\\ln\\left|r(1 - 2x_k)\\right|
    Inputs:
        r: parameter (0 < r <= 4)
        x0: initial value in (0, 1)
        n: iterations averaged (even)
    Outputs: lyapunov (Lyapunov exponent (negative: stable periodic orbit)), attractor (attractor reached)
    See also: help("logistic_map_lyapunov")
    """
    given = {k: v for k, v in dict(r=r, x0=x0, n=n).items() if v is not None}
    return _P.solve("logistic_map_lyapunov", **given)

def logistic_map_two_cycle(r=None):
    """Logistic map: period-2 cycle and its stability. The 2-cycle {p, q} of x -> r x (1 - x) (3 < r <= 4), its multiplier f'(p) f'(q) and stability (stable for 3 < r < 1 + sqrt 6).
    Formula: p, q = \\frac{r + 1 \\mp \\sqrt{(r - 3)(r + 1)}}{2r},\\quad f'(p)f'(q) = 4 + 2r - r^2
    Inputs:
        r: parameter (3 < r <= 4)
    Outputs: p (lower cycle point), q (upper cycle point), multiplier (f'(p) f'(q) = 4 + 2r - r^2), stability (stability)
    See also: help("logistic_map_two_cycle")
    """
    given = {k: v for k, v in dict(r=r).items() if v is not None}
    return _P.solve("logistic_map_two_cycle", **given)

def logistic_value(P0=None, r=None, K=None, t=None):
    """Logistic growth: population at a time. Solve dP/dt = r P (1 - P/K), P(0) = P0, and give P(t).
    Formula: P(t) = \\frac{K}{1 + \\left(\\frac{K}{P_0} - 1\\right)e^{-r t}}
    Inputs:
        P0: initial population (> 0)
        r: intrinsic growth rate (> 0)
        K: carrying capacity (> 0)
        t: time
    Outputs: P (population P(t))
    See also: help("logistic_value")
    """
    given = {k: v for k, v in dict(P0=P0, r=r, K=K, t=t).items() if v is not None}
    return _P.solve("logistic_value", **given)

def lorenz_equilibria(sigma=None, rho=None, beta=None):
    """Lorenz system: equilibria and stability of the origin. Equilibria of x' = sigma(y - x), y' = x(rho - z) - y, z' = xy - beta z: the origin and C+- = (+-sqrt(beta(rho-1)), same, rho - 1).
    Formula: C_\\pm = \\left(\\pm\\sqrt{\\beta(\\rho - 1)}, \\pm\\sqrt{\\beta(\\rho - 1)}, \\rho - 1\\right)
    Inputs:
        sigma: Prandtl number (> 0)
        rho: Rayleigh parameter (> 0)
        beta: geometric factor (> 0)
    Outputs: count (number of equilibria), x_c (x (and y) of C+), z_c (z of C+- (rho - 1)), origin_stability (stability of the origin)
    See also: help("lorenz_equilibria")
    """
    given = {k: v for k, v in dict(sigma=sigma, rho=rho, beta=beta).items() if v is not None}
    return _P.solve("lorenz_equilibria", **given)

def lorenz_hopf_threshold(sigma=None, beta=None):
    """Lorenz system: Hopf threshold rho_H (loss of stability of C+-). The Rayleigh parameter at which the equilibria C+- of the Lorenz system lose stability (subcritical Hopf; chaos follows).
    Formula: \\rho_H = \\frac{\\sigma(\\sigma + \\beta + 3)}{\\sigma - \\beta - 1}
    Inputs:
        sigma: Prandtl number (> beta + 1)
        beta: geometric factor (> 0)
    Outputs: rho_H (Hopf threshold)
    See also: help("lorenz_hopf_threshold")
    """
    given = {k: v for k, v in dict(sigma=sigma, beta=beta).items() if v is not None}
    return _P.solve("lorenz_hopf_threshold", **given)

def lotka_volterra_equilibrium(a=None, b=None, c=None, d=None):
    """Lotka-Volterra predator-prey: coexistence equilibrium and oscillation period. For x' = a x - b x y (prey), y' = -c y + d x y (predator): the coexistence equilibrium and the period of small oscillations about it.
    Formula: (x^*, y^*) = \\left(\\frac{c}{d}, \\frac{a}{b}\\right),\\; T = \\frac{2\\pi}{\\sqrt{ac}}
    Inputs:
        a: prey growth rate (> 0)
        b: predation rate (> 0)
        c: predator death rate (> 0)
        d: predator efficiency (> 0)
    Outputs: x_eq (prey at equilibrium c/d), y_eq (predators at equilibrium a/b), omega (small-oscillation angular frequency sqrt(ac)), period (small-oscillation period 2 pi / sqrt(ac))
    See also: help("lotka_volterra_equilibrium")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, d=d).items() if v is not None}
    return _P.solve("lotka_volterra_equilibrium", **given)

def midpoint_method(f=None, t0=None, y0=None, h=None, n=None):
    """Explicit midpoint method (RK2). Approximate the solution of y' = f(t, y), y(t0) = y0, after n steps of size h with the explicit midpoint method.
    Formula: y_{k+1} = y_k + h f\\left(t_k + \\tfrac{h}{2}, y_k + \\tfrac{h}{2} f(t_k, y_k)\\right)
    Inputs:
        f: right-hand side f(t, y) of y' = f(t, y)
        t0: initial time
        y0: initial value y(t0)
        h: step size (> 0)
        n: number of steps
    Outputs: y_n (approximation of y(t0 + n h)), t_n (final time t0 + n h)
    See also: help("midpoint_method")
    """
    given = {k: v for k, v in dict(f=f, t0=t0, y0=y0, h=h, n=n).items() if v is not None}
    return _P.solve("midpoint_method", **given)

def mixing_tank(V=None, r=None, c_in=None, A0=None, t=None):
    """Mixing tank (brine): amount of salt at a time. A well-stirred tank of volume V with inflow = outflow rate r at concentration c_in: amount A(t) of solute.
    Formula: A(t) = c_{in}V + (A_0 - c_{in}V)e^{-rt/V}
    Inputs:
        V: volume (constant, > 0)
        r: flow rate in = out (> 0)
        c_in: inflow concentration (>= 0)
        A0: initial amount of solute
        t: time
    Outputs: A (amount A(t)), A_limit (long-run amount c_in V), concentration (concentration A(t)/V)
    See also: help("mixing_tank")
    """
    given = {k: v for k, v in dict(V=V, r=r, c_in=c_in, A0=A0, t=t).items() if v is not None}
    return _P.solve("mixing_tank", **given)

def newton_cooling_constant(T0=None, Ta=None, T1=None, t1=None):
    """Newton's law of cooling: cooling constant from a measurement. The cooling constant k when a body at T0 in surroundings Ta reads T1 after time t1.
    Formula: k = \\frac{1}{t_1}\\ln\\frac{T_0 - T_a}{T_1 - T_a}
    Inputs:
        T0: initial temperature
        Ta: ambient temperature
        T1: measured temperature
        t1: time of the measurement (> 0)
    Outputs: k (cooling constant)
    See also: help("newton_cooling_constant")
    """
    given = {k: v for k, v in dict(T0=T0, Ta=Ta, T1=T1, t1=t1).items() if v is not None}
    return _P.solve("newton_cooling_constant", **given)

def newton_cooling_temperature(T0=None, Ta=None, k=None, t=None):
    """Newton's law of cooling: temperature at a time. Solve dT/dt = -k (T - Ta), T(0) = T0, and give T(t).
    Formula: T(t) = T_a + (T_0 - T_a)e^{-k t}
    Inputs:
        T0: initial temperature
        Ta: ambient temperature
        k: cooling constant (> 0)
        t: time
    Outputs: T (temperature T(t))
    See also: help("newton_cooling_temperature")
    """
    given = {k: v for k, v in dict(T0=T0, Ta=Ta, k=k, t=t).items() if v is not None}
    return _P.solve("newton_cooling_temperature", **given)

def newton_cooling_time(T0=None, Ta=None, k=None, T1=None):
    """Newton's law of cooling: time to reach a temperature. With dT/dt = -k (T - Ta), T(0) = T0: when does the temperature reach T1?
    Formula: t = \\frac{1}{k}\\ln\\frac{T_0 - T_a}{T_1 - T_a}
    Inputs:
        T0: initial temperature
        Ta: ambient temperature
        k: cooling constant (> 0)
        T1: target temperature (between Ta and T0)
    Outputs: t (time to reach T1)
    See also: help("newton_cooling_time")
    """
    given = {k: v for k, v in dict(T0=T0, Ta=Ta, k=k, T1=T1).items() if v is not None}
    return _P.solve("newton_cooling_time", **given)

def nonlinear_equilibrium_type(f=None, g=None, x0=None, y0=None):
    """Nonlinear 2-D system: type of an equilibrium by linearization. For x' = f(x, y), y' = g(x, y) and an equilibrium (x0, y0): the Jacobian there, the equilibrium type and stability (Hartman-Grobman).
    Formula: J = \\begin{pmatrix} f_x & f_y \\\\ g_x & g_y \\end{pmatrix}_{(x_0, y_0)}
    Inputs:
        f: x' = f(x, y)
        g: y' = g(x, y)
        x0: equilibrium x
        y0: equilibrium y
    Outputs: type (type of the linearization), stability (stability (inconclusive for a center or a degenerate case)), jacobian (Jacobian at the equilibrium), trace (trace of the Jacobian), det (determinant of the Jacobian)
    See also: help("nonlinear_equilibrium_type")
    """
    given = {k: v for k, v in dict(f=f, g=g, x0=x0, y0=y0).items() if v is not None}
    return _P.solve("nonlinear_equilibrium_type", **given)

def ode_impulse_response(a=None, b=None, c=None, t=None):
    """Impulse response of a second-order ODE. The response h(t) of a y'' + b y' + c y = delta(t) from rest (the inverse Laplace transform of 1/(a s^2 + b s + c)).
    Formula: h(t) = \\mathcal{L}^{-1}\\left\\{\\frac{1}{as^2 + bs + c}\\right\\}
    Inputs:
        a: coefficient of y'' (condition: a != 0)
        b: coefficient of y'
        c: coefficient of y
        t: time (>= 0)
    Outputs: h (impulse response h(t))
    See also: help("ode_impulse_response")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, t=t).items() if v is not None}
    return _P.solve("ode_impulse_response", **given)

def ode_step_response(a=None, b=None, c=None, t=None):
    """Unit-step response of a second-order ODE. The response of a y'' + b y' + c y = u(t) (unit step) from rest, and its final value 1/c when stable.
    Formula: y(t) = \\mathcal{L}^{-1}\\left\\{\\frac{1}{s(as^2 + bs + c)}\\right\\}
    Inputs:
        a: coefficient of y'' (condition: a != 0)
        b: coefficient of y'
        c: coefficient of y (condition: c != 0)
        t: time (>= 0)
    Outputs: y (step response y(t)), final_value (limit 1/c (stable systems))
    See also: help("ode_step_response")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, t=t).items() if v is not None}
    return _P.solve("ode_step_response", **given)

def partial_fraction_residues(F=None):
    """Partial fractions of a rational function (simple poles). F(s) = sum r_i/(s - p_i): the poles and residues of a strictly proper rational function with simple poles.
    Formula: F(s) = \\sum_i \\frac{r_i}{s - p_i},\\quad r_i = \\frac{P(p_i)}{Q'(p_i)}
    Inputs:
        F: F(s), a rational function of s
    Outputs: poles (poles p_i (real ascending, then complex)), residues (residues r_i in the same order), count (number of poles)
    See also: help("partial_fraction_residues")
    """
    given = {k: v for k, v in dict(F=F).items() if v is not None}
    return _P.solve("partial_fraction_residues", **given)

def phase_portrait_2x2(A=None):
    """Linear 2x2 system: equilibrium type and stability (trace-determinant plane). Classify the origin of x' = A x (node, saddle, spiral, center, star, degenerate) and its stability from the trace and determinant.
    Formula: \\lambda^2 - T\\lambda + D = 0,\\; T = \\operatorname{tr}A,\\; D = \\det A
    Inputs:
        A: the 2x2 coefficient matrix of x' = A x
    Outputs: type (phase portrait type), stability (stability), lambda1 (first eigenvalue), lambda2 (second eigenvalue), trace (trace), det (determinant)
    See also: help("phase_portrait_2x2")
    """
    given = {k: v for k, v in dict(A=A).items() if v is not None}
    return _P.solve("phase_portrait_2x2", **given)

def practical_resonance(m=None, c=None, k=None, F0=None):
    """Damped oscillator: resonance frequency and peak amplitude. For m y'' + c y' + k y = F0 cos(w t): the forcing frequency of maximum steady-state amplitude and that amplitude.
    Formula: \\omega_r = \\sqrt{\\frac{k}{m} - \\frac{c^2}{2m^2}},\\quad A_{\\max} = \\frac{F_0}{c\\sqrt{k/m - c^2/(4m^2)}}
    Inputs:
        m: mass (> 0)
        c: damping coefficient (> 0)
        k: spring constant (> 0)
        F0: forcing amplitude
    Outputs: omega_r (resonance (peak) frequency, 0 when there is no peak), amplitude_max (peak amplitude), has_peak (c^2 < 2 m k)
    See also: help("practical_resonance")
    """
    given = {k: v for k, v in dict(m=m, c=c, k=k, F0=F0).items() if v is not None}
    return _P.solve("practical_resonance", **given)

def quadratic_drag_velocity(m=None, c=None, g=None, v0=None, t=None):
    """Falling body with quadratic drag: velocity. Solve m v' = m g - c v^2 with v(0) = v0 >= 0: velocity at time t and terminal velocity sqrt(m g / c).
    Formula: v(t) = v_t \\tanh\\left(\\frac{g t}{v_t} + \\operatorname{artanh}\\frac{v_0}{v_t}\\right),\\; v_t = \\sqrt{mg/c}
    Inputs:
        m: mass (> 0)
        c: quadratic drag coefficient (> 0)
        g: gravitational acceleration (> 0)
        v0: initial downward velocity (>= 0)
        t: time (>= 0)
    Outputs: v (velocity v(t)), v_terminal (terminal velocity)
    See also: help("quadratic_drag_velocity")
    """
    given = {k: v for k, v in dict(m=m, c=c, g=g, v0=v0, t=t).items() if v is not None}
    return _P.solve("quadratic_drag_velocity", **given)

def quadratic_ode_blowup(k=None, y0=None, t=None):
    """Equation y' = k y^2: solution and blow-up time. Solve y' = k y^2, y(0) = y0; give y(t) and the finite blow-up time 1/(k y0) when k y0 > 0.
    Formula: y(t) = \\frac{y_0}{1 - k y_0 t}
    Inputs:
        k: coefficient
        y0: initial value
        t: time (>= 0)
    Outputs: y (value y(t)), blowup_time (time at which y becomes infinite (k y0 > 0))
    See also: help("quadratic_ode_blowup")
    """
    given = {k: v for k, v in dict(k=k, y0=y0, t=t).items() if v is not None}
    return _P.solve("quadratic_ode_blowup", **given)

def radiometric_age(T=None, p=None):
    """Age from the fraction remaining (radioactive dating). The elapsed time when a fraction p of a radioactive substance with half-life T remains.
    Formula: t = T\\,\\frac{\\ln(1/p)}{\\ln 2}
    Inputs:
        T: half-life (> 0)
        p: fraction remaining, 0 < p <= 1
    Outputs: t (age (elapsed time))
    See also: help("radiometric_age")
    """
    given = {k: v for k, v in dict(T=T, p=p).items() if v is not None}
    return _P.solve("radiometric_age", **given)

def robin_eigenvalues(L=None, h=None, n=None):
    """Eigenvalues with a Robin (convective) end condition. The n-th eigenvalue of y'' + lambda y = 0, y(0) = 0, y'(L) + h y(L) = 0 (heat loss at one end): root of tan(mu L) = -mu/h.
    Formula: \\tan(\\mu L) = -\\frac{\\mu}{h},\\quad \\lambda = \\mu^2
    Inputs:
        L: interval length (> 0)
        h: Robin coefficient (> 0)
        n: index n >= 1
    Outputs: lambda_n (n-th eigenvalue mu_n^2), sqrt_lambda (mu_n)
    See also: help("robin_eigenvalues")
    """
    given = {k: v for k, v in dict(L=L, h=h, n=n).items() if v is not None}
    return _P.solve("robin_eigenvalues", **given)

def routh_hurwitz(coeffs=None):
    """Routh-Hurwitz stability test of a characteristic polynomial. How many roots of a polynomial lie in the right half plane (Routh array), hence whether the system is asymptotically stable.
    Formula: \\#\\{\\operatorname{Re} s > 0\\} = \\text{sign changes in the first column}
    Inputs:
        coeffs: coefficients, highest power first
    Outputs: stable (all roots in the open left half plane), rhp_roots (number of right-half-plane roots), first_column (first column of the Routh array)
    See also: help("routh_hurwitz")
    """
    given = {k: v for k, v in dict(coeffs=coeffs).items() if v is not None}
    return _P.solve("routh_hurwitz", **given)

def runge_kutta_4(f=None, t0=None, y0=None, h=None, n=None):
    """Classical Runge-Kutta method (RK4). Approximate the solution of y' = f(t, y), y(t0) = y0, after n steps of size h with the classical fourth-order Runge-Kutta method.
    Formula: y_{k+1} = y_k + \\tfrac{h}{6}(k_1 + 2k_2 + 2k_3 + k_4)
    Inputs:
        f: right-hand side f(t, y) of y' = f(t, y)
        t0: initial time
        y0: initial value y(t0)
        h: step size (> 0)
        n: number of steps
    Outputs: y_n (approximation of y(t0 + n h)), t_n (final time t0 + n h)
    See also: help("runge_kutta_4")
    """
    given = {k: v for k, v in dict(f=f, t0=t0, y0=y0, h=h, n=n).items() if v is not None}
    return _P.solve("runge_kutta_4", **given)

def runge_kutta_4_system(f=None, g=None, t0=None, x0=None, y0=None, h=None, n=None):
    """RK4 for a system of two first-order equations. Approximate x' = f(t, x, y), y' = g(t, x, y) with x(t0) = x0, y(t0) = y0 after n RK4 steps of size h.
    Formula: \\mathbf{u}_{k+1} = \\mathbf{u}_k + \\tfrac{h}{6}(\\mathbf{k}_1 + 2\\mathbf{k}_2 + 2\\mathbf{k}_3 + \\mathbf{k}_4)
    Inputs:
        f: x' = f(t, x, y)
        g: y' = g(t, x, y)
        t0: initial time
        x0: initial x
        y0: initial y
        h: step size (> 0)
        n: number of steps
    Outputs: x_n (approximation of x(t0 + n h)), y_n (approximation of y(t0 + n h)), t_n (final time)
    See also: help("runge_kutta_4_system")
    """
    given = {k: v for k, v in dict(f=f, g=g, t0=t0, x0=x0, y0=y0, h=h, n=n).items() if v is not None}
    return _P.solve("runge_kutta_4_system", **given)

def second_order_homogeneous_ivp(a=None, b=None, c=None, y0=None, v0=None, t=None):
    """Second-order homogeneous linear ODE: initial value problem. Solve a y'' + b y' + c y = 0 with y(0) = y0, y'(0) = v0 and give y(t) (overdamped, critical or underdamped).
    Formula: y(t) = e^{mt}\\left[y_0\\cosh(\\delta t) + (v_0 - m y_0)\\frac{\\sinh(\\delta t)}{\\delta}\\right],\\; m = -\\frac{b}{2a},\\; \\delta^2 = m^2 - \\frac{c}{a}
    Inputs:
        a: coefficient of y'' (condition: a != 0)
        b: coefficient of y'
        c: coefficient of y
        y0: initial value y(0)
        v0: initial slope y'(0)
        t: time
    Outputs: y (value y(t)), damping (damping case)
    See also: help("second_order_homogeneous_ivp")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, y0=y0, v0=v0, t=t).items() if v is not None}
    return _P.solve("second_order_homogeneous_ivp", **given)

def separable_power(a=None, n=None, y0=None, t=None):
    """Separable equation y' = a t^n y. Solve the separable equation y' = a t^n y with y(0) = y0 and give y(t).
    Formula: y(t) = y_0\\exp\\left(\\frac{a\\,t^{n+1}}{n+1}\\right)
    Inputs:
        a: coefficient
        n: power of t (>= 0)
        y0: initial value
        t: time (>= 0)
    Outputs: y (value y(t))
    See also: help("separable_power")
    """
    given = {k: v for k, v in dict(a=a, n=n, y0=y0, t=t).items() if v is not None}
    return _P.solve("separable_power", **given)

def simple_harmonic_motion(m=None, k=None, x0=None, v0=None, t=None):
    """Simple harmonic motion: position, amplitude, period. Solve m x'' + k x = 0 with x(0) = x0, x'(0) = v0: position at t, amplitude, angular frequency and period.
    Formula: x(t) = x_0\\cos\\omega t + \\frac{v_0}{\\omega}\\sin\\omega t,\\; A = \\sqrt{x_0^2 + (v_0/\\omega)^2}
    Inputs:
        m: mass (> 0)
        k: spring constant (> 0)
        x0: initial position
        v0: initial velocity
        t: time
    Outputs: x (position x(t)), amplitude (amplitude), omega (angular frequency), period (period)
    See also: help("simple_harmonic_motion")
    """
    given = {k: v for k, v in dict(m=m, k=k, x0=x0, v0=v0, t=t).items() if v is not None}
    return _P.solve("simple_harmonic_motion", **given)

def sir_epidemic(beta=None, gamma=None, S0=None, I0=None):
    """SIR epidemic: R0, peak infections and final size. For S' = -beta S I, I' = beta S I - gamma I (fractions of the population): R0, the peak infected fraction and the final susceptible fraction.
    Formula: I_{\\max} = S_0 + I_0 - \\frac{1 + \\ln(R_0 S_0)}{R_0},\\quad \\ln\\frac{S_\\infty}{S_0} = R_0(S_\\infty - S_0 - I_0)
    Inputs:
        beta: transmission rate (> 0)
        gamma: recovery rate (> 0)
        S0: initial susceptible fraction
        I0: initial infected fraction
    Outputs: R0 (basic reproduction number beta/gamma), I_max (peak infected fraction), S_inf (final susceptible fraction), attack_rate (fraction infected during the epidemic S0 - S_inf)
    See also: help("sir_epidemic")
    """
    given = {k: v for k, v in dict(beta=beta, gamma=gamma, S0=S0, I0=I0).items() if v is not None}
    return _P.solve("sir_epidemic", **given)

def slope_field(f=None, t=None, y=None):
    """Slope (direction) field value. The slope dy/dt = f(t, y) of the direction field at a point, and its angle.
    Formula: m = f(t, y),\\; \\theta = \\arctan m
    Inputs:
        f: right-hand side f(t, y)
        t: t-coordinate
        y: y-coordinate
    Outputs: slope (slope f(t, y)), angle_deg (angle of the field line, degrees)
    See also: help("slope_field")
    """
    given = {k: v for k, v in dict(f=f, t=t, y=y).items() if v is not None}
    return _P.solve("slope_field", **given)

def steady_state_amplitude(a=None, b=None, c=None, F0=None, w=None):
    """Forced damped oscillator: steady-state amplitude and phase. Steady-state response of a y'' + b y' + c y = F0 cos(w t): amplitude, phase lag and gain.
    Formula: A = \\frac{F_0}{\\sqrt{(c - a\\omega^2)^2 + (b\\omega)^2}},\\; \\tan\\delta = \\frac{b\\omega}{c - a\\omega^2}
    Inputs:
        a: mass-like coefficient (> 0)
        b: damping (> 0)
        c: stiffness (> 0)
        F0: forcing amplitude
        w: forcing angular frequency (> 0)
    Outputs: amplitude (steady-state amplitude), phase_lag (phase lag in radians (0 to pi)), gain (amplitude per unit force)
    See also: help("steady_state_amplitude")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, F0=F0, w=w).items() if v is not None}
    return _P.solve("steady_state_amplitude", **given)

def sturm_liouville_eigenvalues(bc=None, L=None, n=None):
    """Eigenvalues of y'' + lambda y = 0 with Dirichlet/Neumann ends. The n-th eigenvalue and eigenfunction of y'' + lambda y = 0 on [0, L] with Dirichlet (y = 0) or Neumann (y' = 0) conditions at each end.
    Formula: \\lambda_n = \\left(\\frac{n\\pi}{L}\\right)^2 \\text{ (DD, NN)},\\quad \\left(\\frac{(n - \\frac12)\\pi}{L}\\right)^2 \\text{ (mixed)}
    Inputs:
        bc: boundary conditions at x = 0 and x = L
        L: interval length (> 0)
        n: index n >= 1 (Neumann-Neumann also has lambda_0 = 0)
    Outputs: lambda_n (n-th eigenvalue), sqrt_lambda (sqrt(lambda_n)), eigenfunction (eigenfunction)
    See also: help("sturm_liouville_eigenvalues")
    """
    given = {k: v for k, v in dict(bc=bc, L=L, n=n).items() if v is not None}
    return _P.solve("sturm_liouville_eigenvalues", **given)

def torricelli_draining(h0=None, k=None, t=None):
    """Draining tank (Torricelli's law): height and emptying time. Solve dh/dt = -k sqrt(h), h(0) = h0: water height at time t and the time to empty.
    Formula: h(t) = \\left(\\sqrt{h_0} - \\tfrac{k t}{2}\\right)^2,\\; t_{empty} = \\frac{2\\sqrt{h_0}}{k}
    Inputs:
        h0: initial height (> 0)
        k: drain constant (> 0)
        t: time (>= 0)
    Outputs: h (height h(t) (0 once empty)), t_empty (time to empty 2 sqrt(h0)/k)
    See also: help("torricelli_draining")
    """
    given = {k: v for k, v in dict(h0=h0, k=k, t=t).items() if v is not None}
    return _P.solve("torricelli_draining", **given)

def undamped_resonance(m=None, k=None, F0=None, t=None):
    """Undamped resonance: growing response. m y'' + k y = F0 cos(w0 t) forced exactly at the natural frequency, starting from rest: y(t) and its linearly growing envelope.
    Formula: y(t) = \\frac{F_0}{2m\\omega_0}\\,t\\sin(\\omega_0 t),\\quad \\omega_0 = \\sqrt{k/m}
    Inputs:
        m: mass (> 0)
        k: spring constant (> 0)
        F0: forcing amplitude
        t: time
    Outputs: y (displacement y(t)), envelope (amplitude envelope F0 t / (2 m w0)), omega0 (natural frequency)
    See also: help("undamped_resonance")
    """
    given = {k: v for k, v in dict(m=m, k=k, F0=F0, t=t).items() if v is not None}
    return _P.solve("undamped_resonance", **given)

def undetermined_coefficients_exponential(a=None, b=None, c=None, F=None, s=None, y0=None, v0=None, t=None):
    """Undetermined coefficients: exponential forcing. Solve a y'' + b y' + c y = F e^{s t}, y(0) = y0, y'(0) = v0: the particular coefficient (with resonance) and y(t).
    Formula: y_p = \\frac{F}{a s^2 + b s + c}\\,e^{st}
    Inputs:
        a: coefficient of y'' (condition: a != 0)
        b: coefficient of y'
        c: coefficient of y
        F: forcing amplitude
        s: forcing exponent
        y0: initial value
        v0: initial slope
        t: time
    Outputs: y (value y(t)), A (coefficient of the particular solution A t^m e^{st}), resonance_multiplicity (m: 0, or 1/2 when s is a simple/double characteristic root)
    See also: help("undetermined_coefficients_exponential")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, F=F, s=s, y0=y0, v0=v0, t=t).items() if v is not None}
    return _P.solve("undetermined_coefficients_exponential", **given)

def undetermined_coefficients_polynomial(a=None, b=None, c=None, p=None, y0=None, v0=None, t=None):
    """Undetermined coefficients: polynomial forcing. Solve a y'' + b y' + c y = p0 + p1 t + ... (degree <= 4), y(0) = y0, y'(0) = v0: particular polynomial and y(t).
    Formula: y_p = \\sum_k q_k t^k,\\quad c\\,q_k + b(k+1)q_{k+1} + a(k+2)(k+1)q_{k+2} = p_k
    Inputs:
        a: coefficient of y'' (condition: a != 0)
        b: coefficient of y'
        c: coefficient of y (condition: c != 0)
        p: forcing coefficients p0, p1, ... (ascending powers of t)
        y0: initial value
        v0: initial slope
        t: time
    Outputs: y (value y(t)), particular (coefficients q0, q1, ... of the particular polynomial)
    See also: help("undetermined_coefficients_polynomial")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, p=p, y0=y0, v0=v0, t=t).items() if v is not None}
    return _P.solve("undetermined_coefficients_polynomial", **given)

def wave_equation_string_series(f=None, L=None, c=None, N=None, x=None, t=None, g=None):
    """Vibrating string with fixed ends: Fourier series value. u(x, t) for u_tt = c^2 u_xx, u(0, t) = u(L, t) = 0, u(x, 0) = f(x), u_t(x, 0) = g(x) (polynomials), from N series terms.
    Formula: u = \\sum_{n=1}^{N}\\left[b_n\\cos\\frac{n\\pi c t}{L} + \\frac{B_n L}{n\\pi c}\\sin\\frac{n\\pi c t}{L}\\right]\\sin\\frac{n\\pi x}{L}
    Inputs:
        f: initial profile f(x), a polynomial
        L: string length (> 0)
        c: wave speed (> 0)
        N: number of series terms
        x: position (0 <= x <= L)
        t: time
        g: initial velocity g(x), a polynomial (default 0) (optional)
    Outputs: u (displacement u(x, t) from N terms)
    See also: help("wave_equation_string_series")
    """
    given = {k: v for k, v in dict(f=f, L=L, c=c, N=N, x=x, t=t, g=g).items() if v is not None}
    return _P.solve("wave_equation_string_series", **given)


